## Own acquisition, replacement and release

A resource owner has one lifecycle from acquisition to release. Establish:

- who acquires, publishes and disposes it;
- what happens if acquisition fails partway through;
- how replacement invalidates the previous instance and pending callbacks;
- which cleanup operations are safe to repeat;
- whether a consumer is borrowing a shared resource or owns it exclusively.

A disposer returned by a subscription should remove that registration only.
Cleanup from an old component must not destroy a replacement owned by another
mount. Do not close a shared connection whenever one subscriber disappears.
Use framework cleanup where possible; choose a class/closure only if it makes
resource identity and lifecycle clearer than the existing owner.

import react from '@vitejs/plugin-react'
import { defineConfig } from 'vite'

export default defineConfig({ plugins: [react()] })

import { type ReactNode, useId, useState } from 'react'
import { createPortal } from 'react-dom'

type DialogProps = {
  children: ReactNode
  description: string
  title: string
  triggerLabel: string
}

export function Dialog({ children, description, title, triggerLabel }: DialogProps) {
  const [open, setOpen] = useState(false)
  const titleId = useId()
  const descriptionId = useId()

  return (
    <>
      <button type="button" onClick={() => setOpen(true)}>
        {triggerLabel}
      </button>
      {open &&
        createPortal(
          <div className="overlay" onClick={() => setOpen(false)}>
            <section
              aria-describedby={descriptionId}
              aria-labelledby={titleId}
              className="dialog"
              role="dialog"
              onClick={(event) => event.stopPropagation()}
            >
              <h2 id={titleId}>{title}</h2>
              <p id={descriptionId}>{description}</p>
              {children}
              <button type="button" onClick={() => setOpen(false)}>
                Close
              </button>
            </section>
          </div>,
          document.body,
        )}
    </>
  )
}

.overlay {
  align-items: center;
  background: rgb(0 0 0 / 55%);
  display: flex;
  inset: 0;
  justify-content: center;
  position: fixed;
}

.dialog {
  background: white;
  color: black;
  display: grid;
  gap: 1rem;
  max-width: 28rem;
  padding: 2rem;
}

import { defineConfig, devices } from '@playwright/test'

export default defineConfig({
  testDir: './tests',
  fullyParallel: false,
  use: {
    ...devices['Desktop Chrome'],
    baseURL: 'http://127.0.0.1:4173',
  },
  webServer: {
    command: 'npm run build && npx vite preview --host 127.0.0.1 --port 4173',
    port: 4173,
    reuseExistingServer: false,
  },
})

import assert from 'node:assert/strict'
import { chromium, expect } from '@playwright/test'
import { createServer } from 'vite'

// Host acceptance uses the supplied demo's public controls, independently of
// the implementation's chosen browser-test transport or package build layout.
const server = await createServer({
  server: { host: '127.0.0.1', port: 0, strictPort: true, middlewareMode: false },
  logLevel: 'error',
})
let browser
try {
  await server.listen()
  const address = server.httpServer.address()
  assert.ok(address && typeof address === 'object')
  browser = await chromium.launch()
  const page = await browser.newPage()
  await page.goto(`http://127.0.0.1:${address.port}`)
  const trigger = page.getByRole('button', { name: 'Edit profile' })
  await trigger.click()
  const dialog = page.getByRole('dialog', { name: 'Edit profile' })
  await expect(dialog).toBeVisible()
  await expect(dialog.getByLabel('Name')).toBeFocused()
  await page.locator('.overlay').click({ position: { x: 4, y: 4 } })
  await expect(dialog).toBeHidden()
  await page.evaluate(() => new Promise(resolve =>
    requestAnimationFrame(() => requestAnimationFrame(resolve))))
  await expect(trigger).toBeFocused()
  await trigger.click()
  await expect(dialog).toBeVisible()
  await page.keyboard.press('Escape')
  await expect(dialog).toBeHidden()
  await expect(trigger).toBeFocused()
  console.log('Host public-contract check passed: outside dismissal settles on trigger; reopen/Escape returns focus.')
} finally {
  await browser?.close()
  await server.close()
}

// @vitest-environment node

import { renderToString } from 'react-dom/server'
import { expect, test } from 'vitest'

import { Dialog } from './Dialog'

test('renders the closed primitive without accessing browser globals', () => {
  const html = renderToString(
    <Dialog title="Example" description="Description" triggerLabel="Open">
      <button type="button">Action</button>
    </Dialog>,
  )

  expect(html).toContain('Open')
})

